SELECT CASE WHEN s.risk_reward_ratio < 0.5 THEN 'a_lt0.5' WHEN s.risk_reward_ratio < 1 THEN 'b_0.5-1' WHEN s.risk_reward_ratio < 1.5 THEN 'c_1-1.5' ELSE 'd_ge1.5' END AS rr_bucket, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losers, SUM(p.status='STOPPED') AS stopped, ROUND(SUM(p.realized_pnl),4) AS pnl_gross, ROUND(SUM(p.realized_pnl - 0.001*p.quantity*(p.entry_price + p.exit_price)),4) AS pnl_after_fee, ROUND(AVG((s.take_profit - s.latest_price)/s.latest_price*100),3) AS avg_tp_pct, ROUND(AVG((s.latest_price - s.stop_loss)/s.latest_price*100),3) AS avg_sl_pct, SUM((s.take_profit - s.latest_price)/s.latest_price*100 < 0.2) AS tp_below_fee_n FROM crypto_ai.paper_position p JOIN crypto_ai.trade_signal s ON s.id = p.signal_id WHERE p.closed_at IS NOT NULL GROUP BY rr_bucket ORDER BY rr_bucket;
SELECT CASE WHEN w.entry_quality_score < 55 THEN 'a_50-54' WHEN w.entry_quality_score < 70 THEN 'b_55-69' WHEN w.entry_quality_score < 85 THEN 'c_70-84' ELSE 'd_85+' END AS eq_bucket, COUNT(*) AS n, SUM(p.realized_pnl < 0) AS losers, SUM(p.status='STOPPED') AS stopped, ROUND(SUM(p.realized_pnl),4) AS pnl_gross, ROUND(SUM(p.realized_pnl - 0.001*p.quantity*(p.entry_price + p.exit_price)),4) AS pnl_after_fee FROM crypto_ai.paper_position p JOIN crypto_ai.wallet_managed_position w ON w.entry_signal_id = p.signal_id WHERE p.closed_at IS NOT NULL GROUP BY eq_bucket ORDER BY eq_bucket;
SELECT p.id, p.realized_pnl, ROUND(p.realized_pnl - 0.001*p.quantity*(p.entry_price + p.exit_price),6) AS pnl_after_fee FROM crypto_ai.paper_position p WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id;